import{_ as a,o as e,c as s,a4 as d}from"./chunks/framework.BBs01uty.js";const u=JSON.parse('{"title":"线上问题排查","description":"","frontmatter":{},"headers":[],"relativePath":"service/troubleshooting.md","filePath":"service/troubleshooting.md"}'),n={name:"service/troubleshooting.md"};function p(o,t,l,r,i,c){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="线上问题排查" tabindex="-1">线上问题排查 <a class="header-anchor" href="#线上问题排查" aria-label="Permalink to &quot;线上问题排查&quot;">​</a></h1><blockquote><p><strong>优先级：P1（面试加分 + 实战必备）</strong> — 面试聊项目时，&quot;线上 OOM 你怎么排查&quot;是区分中级和高级的经典题。本文给一套可操作的排查流程。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">背景</p><p>JS 侧排查线上问题靠 devtools + pm2 logs；Java 侧靠 JDK 自带工具链（jps/jstack/jmap/jstat）+ 日志。套路是固定的：先看现象 → 定位进程 → 抓现场 → 分析根因。</p></div><h2 id="排查工具链" tabindex="-1">排查工具链 <a class="header-anchor" href="#排查工具链" aria-label="Permalink to &quot;排查工具链&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>常用场景</th></tr></thead><tbody><tr><td><code>jps</code></td><td>列出 Java 进程</td><td>找到目标进程 PID（或 <code>ps -ef | grep java</code>）</td></tr><tr><td><code>jstack &lt;pid&gt;</code></td><td>线程栈快照</td><td>死锁、线程卡死、CPU 飙高时看线程在干嘛</td></tr><tr><td><code>jmap -heap &lt;pid&gt;</code></td><td>堆内存概况</td><td>内存占用异常时看堆配置和用量</td></tr><tr><td><code>jmap -dump:format=b,file=heap.hprof &lt;pid&gt;</code></td><td>堆快照 dump</td><td>OOM 时抓现场，用 MAT 分析</td></tr><tr><td><code>jstat -gc &lt;pid&gt; 1000</code></td><td>GC 统计（每秒）</td><td>看 GC 频率/耗时，判断是否频繁 Full GC</td></tr><tr><td><code>jcmd</code></td><td>综合诊断命令</td><td>JDK 8+ 替代部分 jmap 功能</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 常用组合</span></span>
<span class="line"><span>jps -l                       # 找进程</span></span>
<span class="line"><span>jstack 12345 &gt; thread.txt    # 抓线程栈</span></span>
<span class="line"><span>jmap -dump:format=b,file=heap.hprof 12345   # 抓堆快照</span></span></code></pre></div><h2 id="场景一-oom-内存溢出-排查-必考" tabindex="-1">场景一：OOM（内存溢出）排查（必考） <a class="header-anchor" href="#场景一-oom-内存溢出-排查-必考" aria-label="Permalink to &quot;场景一：OOM（内存溢出）排查（必考）&quot;">​</a></h2><p><strong>现象</strong>：日志出现 <code>OutOfMemoryError: Java heap space</code>，或服务重启。</p><p><strong>排查流程</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 确认堆内存参数：jmap -heap &lt;pid&gt; 看 -Xmx 配置是否合理</span></span>
<span class="line"><span>2. 抓堆快照：OOM 前 dump（生产配置 -XX:+HeapDumpOnOutOfMemoryError 自动抓）</span></span>
<span class="line"><span>3. 用 MAT / JProfiler 分析 hprof 文件：</span></span>
<span class="line"><span>   - 看 Dominator Tree（支配树）：哪个对象占内存最多</span></span>
<span class="line"><span>   - 看 GC Roots 引用链：谁还持有这些对象（常见：缓存 Map 无限增长、ThreadLocal 没 remove）</span></span>
<span class="line"><span>4. 定位代码：集合类静态变量、连接未关闭、大对象</span></span></code></pre></div><p><strong>三类典型 OOM</strong>：</p><table tabindex="0"><thead><tr><th>类型</th><th>常见原因</th><th>排查方向</th></tr></thead><tbody><tr><td>Heap space</td><td>对象堆积（缓存不淘汰、list 无限 add）</td><td>MAT 看大对象</td></tr><tr><td>Metaspace</td><td>动态生成类太多（CGLIB/反射）</td><td>检查代理生成量</td></tr><tr><td>Direct buffer memory</td><td>NIO 堆外内存泄漏</td><td>检查 ByteBuffer 释放</td></tr></tbody></table><h2 id="场景二-cpu-飙高-必考" tabindex="-1">场景二：CPU 飙高（必考） <a class="header-anchor" href="#场景二-cpu-飙高-必考" aria-label="Permalink to &quot;场景二：CPU 飙高（必考）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. top 找 CPU 高的进程 PID</span></span>
<span class="line"><span>2. top -Hp &lt;pid&gt; 找 CPU 高的线程 TID</span></span>
<span class="line"><span>3. printf &#39;%x&#39; &lt;TID&gt; 转 16 进制</span></span>
<span class="line"><span>4. jstack &lt;pid&gt; | grep -A 20 &lt;16进制TID&gt;   # 看该线程在干嘛</span></span></code></pre></div><p><strong>常见根因</strong>：</p><ul><li>死循环 / while(true) 无 sleep</li><li>频繁 Full GC（内存不足，GC 线程吃 CPU）→ 配合 jstat 确认</li><li>正则回溯、大循环内做重计算</li><li>线程池配置过大，疯狂创建线程</li></ul><p><strong>答题模板</strong>：top 找 PID → top -Hp 找 TID → 转 16 进制 → jstack 定位代码行。这条链路是面试加分细节。</p><h2 id="场景三-接口变慢-卡死" tabindex="-1">场景三：接口变慢 / 卡死 <a class="header-anchor" href="#场景三-接口变慢-卡死" aria-label="Permalink to &quot;场景三：接口变慢 / 卡死&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 先看是不是 DB 慢：慢查询日志 + explain（见 MySQL 篇）</span></span>
<span class="line"><span>2. 看是不是锁等待：jstack 找 BLOCKED 状态的线程，看等哪把锁</span></span>
<span class="line"><span>3. 看是不是连接池耗尽：druid/连接池监控，活跃连接满</span></span>
<span class="line"><span>4. 看是不是 GC 停顿：jstat -gc 观察 Full GC 频率</span></span>
<span class="line"><span>5. 看外部调用超时：Feign/HTTP 调用无超时时间 → 线程挂满</span></span></code></pre></div><p><strong>线程状态速记</strong>：<code>RUNNABLE</code>（跑/等待 IO）、<code>BLOCKED</code>（等锁）、<code>WAITING</code>/<code>TIMED_WAITING</code>（等条件）、<code>DEAD</code>。</p><h2 id="场景四-死锁排查" tabindex="-1">场景四：死锁排查 <a class="header-anchor" href="#场景四-死锁排查" aria-label="Permalink to &quot;场景四：死锁排查&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jstack &lt;pid&gt; | grep -A 20 &quot;Found one Java-level deadlock&quot;</span></span></code></pre></div><p>jstack 直接会输出死锁检测结果：哪些线程互相持锁等待。解决：统一加锁顺序、避免嵌套锁。</p><h2 id="日志与监控-常规手段" tabindex="-1">日志与监控（常规手段） <a class="header-anchor" href="#日志与监控-常规手段" aria-label="Permalink to &quot;日志与监控（常规手段）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>手段</th><th>用途</th></tr></thead><tbody><tr><td>应用日志（Logback）</td><td>ERROR/WARN 分级，关键业务打日志</td></tr><tr><td><strong>链路 ID（traceId）</strong></td><td>请求入口生成，贯穿日志（MDC），排查跨服务问题</td></tr><tr><td>指标监控（Prometheus + Grafana）</td><td>CPU/内存/QPS/GC 曲线，报警</td></tr><tr><td>告警</td><td>错误率/延迟/QPS 异常触发（钉钉/邮件）</td></tr></tbody></table><p><strong>面试题：线上出问题怎么定位？</strong>——分层：先监控看现象（哪个服务/接口异常）→ 看日志（traceId 串链路）→ 根据异常类型走对应工具（OOM→jmap，CPU→jstack）。</p><h2 id="面试题速查" tabindex="-1">面试题速查 <a class="header-anchor" href="#面试题速查" aria-label="Permalink to &quot;面试题速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>一句话答案</th></tr></thead><tbody><tr><td>OOM 怎么排查</td><td>HeapDumpOnOutOfMemoryError + MAT 分析大对象与引用链</td></tr><tr><td>CPU 高怎么排查</td><td>top → top -Hp → TID 转 16 进制 → jstack 定位代码</td></tr><tr><td>jstack 能查什么</td><td>线程状态、死锁、卡在哪</td></tr><tr><td>接口变慢先查什么</td><td>慢 SQL → 锁等待 → 连接池 → GC → 外部调用超时</td></tr><tr><td>怎么定位死锁</td><td>jstack 自带死锁检测输出</td></tr><tr><td>生产怎么防 OOM</td><td>参数合理 + 缓存有界 + 连接释放 + 压测验证</td></tr></tbody></table><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/knowledge/service/java-jvm.html">JVM 入门</a> - OOM 的内存分区背景</li><li><a href="/knowledge/service/mysql-advanced.html">MySQL 进阶</a> - 慢 SQL 排查</li><li><a href="/knowledge/service/spring-cloud.html">Spring Cloud 微服务</a> - 链路追踪 traceId</li></ul>`,30)])])}const g=a(n,[["render",p]]);export{u as __pageData,g as default};
